style.css:
@-moz-document domain("roblox.com") {
body {
        background: url("https://i.imgur.com/4yofSyQ.png") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Optional: make page elements more transparent so the background shows better */
    .container-main, .game-details, .navbar, .content, .footer {
        background-color: rgba(0, 0, 0, 0.6) !important;
    }

    /* Optional: change text color */
    body, h1, h2, h3, p, span, a {
        color: #fff !important;
    }
}
